using System.Text.RegularExpressions;

namespace FsAnalyser.Core.Tests;

// Code review of SL-008: a using directive that names RescanAsAdministrator lets a bare Start(...) reach the elevation call
// without spelling RescanAsAdministrator.Start, so the call-site rule must fire on every spelling of one.
public class CrSl008UsingDirectiveSpellingsTests
{
    private const string CallSiteRule = "only the window's own handler calls the rescan start, and nothing else names the handler";

    [Theory]
    [InlineData("using static global::FsAnalyser.App.RescanAsAdministrator;")]
    [InlineData("using RA = global::FsAnalyser.App.RescanAsAdministrator;")]
    [InlineData("using static FsAnalyser.App . RescanAsAdministrator;")]
    public void TheCallSiteRuleFiresOnAUsingDirectiveThatNamesTheClass(string line)
    {
        SettledRulesCorpusTests.Rule rule = SettledRulesCorpusTests.ReadRule(CallSiteRule);
        Assert.Contains(rule.Patterns, p => Regex.IsMatch(line, p));
    }
}

using System.Text.RegularExpressions;

namespace FsAnalyser.Core.Tests;

// SL-008 review, input pass: the COM elevation moniker has two levels, Administrator and Highest; both elevate with no verb.
public class RescanElevationMonikerHighestTests
{
    [Theory]
    [InlineData("            var moniker = \"Elevation:Highest!new:{3E5FC7F9-9A51-4367-9063-A120244FBEC7}\";")]
    [InlineData("            object o = CoGetObject(\"Elevation:highest!new:\" + clsid, ref bind, iid);")]
    public void TheElevationRuleCatchesTheHighestLevelOfTheMoniker(string line)
    {
        SettledRulesCorpusTests.Rule rule = SettledRulesCorpusTests.ReadRule("only the rescan button's file asks Windows for elevation");
        Assert.Contains(rule.Patterns, p => Regex.IsMatch(line, p));
    }
}

findings.fix:
Use '(?m)\busing\s+static\s+(global::)?[\w.\s]*\bRescanAsAdministrator\b' and '(?m)\busing\s+\w+\s*=\s*(global::)?[\w.\s]*\bRescanAsAdministrator\b' in both fitness.yaml and RescanElevationGuardTests.cs:95-96. Add corpus rows under the call-site rule:
- E17 'using static global::FsAnalyser.App.RescanAsAdministrator;' (fire);
- E18 'using RA = global::FsAnalyser.App.RescanAsAdministrator;' (fire);
- E19 'using static FsAnalyser.App .RescanAsAdministrator;' (fire).
To cover forwarders, either widen Start's boundary to '\bRescanAsAdministrator\s*\.\s*Start\w*' or add a fact that RescanAsAdministrator.cs calls its start delegate only inside Start's body.

